CREATE TABLE outbox_events (id UUID PRIMARY KEY, aggregate_id VARCHAR(255) NOT NULL, topic VARCHAR(255) NOT NULL, payload TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, published_at TIMESTAMP WITH TIME ZONE, attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX outbox_pending ON outbox_events(published_at,created_at);
CREATE TABLE promotions (id UUID PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, description VARCHAR(2000) NOT NULL, status VARCHAR(255) NOT NULL, discount_type VARCHAR(255), discount_value NUMERIC(19,4), currency VARCHAR(3), start_at TIMESTAMPTZ NOT NULL, end_at TIMESTAMPTZ NOT NULL, total_redemption_limit BIGINT NOT NULL, per_customer_limit INTEGER NOT NULL, budget_limit NUMERIC(19,2), rule_version_id UUID NOT NULL, segment VARCHAR(255), channel VARCHAR(255), created_by VARCHAR(255), approved_by VARCHAR(255), version BIGINT NOT NULL, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ, history_json TEXT);
CREATE INDEX promotion_status_dates ON promotions(status,start_at,end_at);
